    directions: {north: 'nord', east: 'est', south: 'sud', west: 'ouest'}, directionPhrases: {north: 'vers le nord', east: 'vers l’est', south: 'vers le sud', west: 'vers l’ouest'},
    commands: {move: 'Avancer d’une case', jump: 'Sauter de 2 cases', right: 'Tourner à 90° à droite', left: 'Tourner à 90° à gauche', interact: 'Ouvrir le coffre'},
    chests: [
      {title: 'Bonjour, je suis Alejandro', kicker: 'COFFRE 1 · À PROPOS', badge: 'Curiosité · rencontrer le créateur', text: 'Je suis étudiant en génie logiciel à l’Universidad Cooperativa de Colombia. J’aime apprendre en construisant : transformer une idée en solution, puis l’améliorer étape par étape. En dehors du code, j’adore les motos et les abeilles.', highlights: ['J’étudie le génie logiciel à l’Universidad Cooperativa de Colombia.', 'Les motos et les abeilles comptent parmi mes grands centres d’intérêt.']},
      {title: 'Les compétences que je cultive', kicker: 'COFFRE 2 · APPRENTISSAGE', badge: 'Cybersécurité · curiosité en action', text: 'J’aime beaucoup découvrir la cybersécurité. En tant qu’étudiant en génie logiciel, je veux comprendre comment protéger les systèmes, repérer les risques et concevoir une technologie plus responsable. Je construis ces bases pas à pas et j’explore ce domaine avec curiosité.', highlights: ['Centre d’intérêt actuel : cybersécurité et protection des systèmes.', 'Ma formation en logiciel m’aide à relier sécurité et création d’applications.']},
      {title: 'Projets en cours', kicker: 'COFFRE 3 · PROJETS', badge: 'Création · des idées prennent forme', text: 'Ces projets viennent de centres d’intérêt variés : la technologie pour les motards, les expériences d’apprentissage, les liens personnels et les outils d’intelligence artificielle. Chaque carte présente le contenu de son dépôt ou de son site.', highlights: []},
      {title: 'En dehors du code', kicker: 'COFFRE 4 · CENTRES D’INTÉRÊT', badge: 'Motos · abeilles · curiosité', text: 'Les motos me passionnent pour tout ce qui entoure une sortie : les machines, leurs modifications et les histoires qui jalonnent la route. J’aime aussi les abeilles ; leur univers me fascine et chaque contribution compte. Ces passions nourrissent ma curiosité et me donnent de nouvelles idées à réaliser.', highlights: ['Motos : une passion qui a aussi inspiré des projets.', 'Abeilles : un intérêt personnel présent dans le nom et l’esprit de ce jeu.']},
      {title: 'Ce qui m’inspire', kicker: 'COFFRE 5 · HISTOIRES ET IDÉES', badge: 'Imagination · créer avec du sens', text: 'J’aime créer des expériences qui relient une histoire à ce qui compte pour la personne qui joue. Jakelin’s World est un jeu narratif en 2D que j’ai créé pour une personne très spéciale : il rassemble des mini-jeux autour de ses goûts et son développement continue. J’aimerais aussi créer des jeux pour enfants avec des défis bienveillants, des idées claires et une place pour apprendre en jouant.', highlights: ['Jakelin’s World : jeu narratif en 2D avec des mini-jeux, en cours de développement.', 'Les jeux pour enfants et la ludification peuvent éveiller la curiosité.']},
      {title: 'Dernier coffre · Contact', kicker: 'COFFRE FINAL · OBJECTIF ET CONTACT', badge: 'Réussite · Explorateur du sentier', text: 'Vous avez trouvé la dernière étape ! Merci d’avoir parcouru le sentier et découvert un peu de mon univers. J’aime apprendre, partager des idées et continuer à créer. Si un projet vous intéresse ou si vous souhaitez discuter, retrouvez-moi ici.', highlights: ['Instagram · @alejojcastro', 'GitHub · Abejandr0']}
    ],
